// UL is the upgrade points spent on the piece, as in the wiki's "Increases Light ATK by UL/2".
// Data generated by `scripts/build-item-effects.mjs`.
import type { ArmorUpgradePoints, ElementKey, ResistKey, StatKey, TetraAlignment, WeaponUpgradePoints } from '../types';
import content from '../data/content/item-effects.json';

export interface ItemEffectValue {
  kind: 'stat' | 'buffStat' | 'derived' | 'elementalAttack' | 'resistance';
  key: string;
  base: number;
  ulMultiplier: number;
  /** Top of a wiki rolled range ("+2-4 CEL"); each dropped copy rolls once and keeps it. */
  rollMax?: number;
  /** Label for a manually selected battle-state value rather than an item roll. */
  controlLabel?: string;
  /** Written for a Fire alignment; the item's chosen crystal decides the real element or stat. */
  tetra?: boolean;
}

export const isTetraItem = (effects: ItemEffect[]) => effects.some(effect => effect.effects.some(value => value.tetra));

export interface ItemEffect {
  name: string;
  description: string;
  /** `conditional` is gated on something the calculator cannot see; `reference` carries no numbers. */
  applies: 'always' | 'conditional' | 'reference';
  effects: ItemEffectValue[];
  /** Switching it on ends the item's other exclusive effects (the Magical Gauntlet's shields). */
  exclusive?: boolean;
}

const WEAPON_EFFECTS = content.weapons as Record<string, ItemEffect[]>;
const ARMOR_EFFECTS = content.armors as Record<string, ItemEffect[]>;
const GEAR_EFFECTS = content.gear as Record<string, ItemEffect[]>;

export function weaponEffects(name: string | null | undefined): ItemEffect[] {
  return (name && WEAPON_EFFECTS[name]) || [];
}

export function armorEffects(name: string | null | undefined): ItemEffect[] {
  return (name && ARMOR_EFFECTS[name]) || [];
}

/** The wiki gives these slots no stat columns, so they contribute only through effects. */
export function gearEffects(name: string | null | undefined): ItemEffect[] {
  return (name && GEAR_EFFECTS[name]) || [];
}

/** The wiki's UL is one number; the calculator's per-channel points are summed. */
export function weaponUL(points: WeaponUpgradePoints | undefined): number {
  if (!points) return 0;
  return points.power + points.critical + points.accuracy + points.durability;
}

export function armorUL(points: ArmorUpgradePoints | undefined): number {
  if (!points) return 0;
  // Three channels: a torso has no durability track.
  return points.armor + points.magicArmor + points.evade;
}

export function valueAtUL(value: ItemEffectValue, ul: number, roll?: number): number {
  const rolled = value.rollMax === undefined ? value.base : clampRoll(value, roll);
  return Math.floor(rolled + ul * value.ulMultiplier);
}

export function clampRoll(value: ItemEffectValue, roll: number | undefined): number {
  if (value.rollMax === undefined) return value.base;
  if (roll === undefined || !Number.isFinite(roll)) return value.base;
  return Math.min(Math.max(Math.floor(roll), value.base), value.rollMax);
}

/** Per value, not per effect: Bands of the Crocodile is "+1-3 WIL, +1-2 DEF". */
export function itemRollKey(itemName: string, effectIndex: number, valueIndex: number): string {
  return `${itemName}:${effectIndex}:${valueIndex}`;
}

export interface ItemBonuses {
  stats: Partial<Record<StatKey, number>>;
  derived: Record<string, number>;
  elementalAttack: Partial<Record<ElementKey, number>>;
  /** Armour text is not read for these; its curated resistance map already applies them. */
  resistances: Partial<Record<ResistKey, number>>;
}

const EMPTY: ItemBonuses = { stats: {}, derived: {}, elementalAttack: {}, resistances: {} };
const NO_ROLLS: Record<string, number> = Object.freeze({});

export function itemConditionalKey(itemName: string, index: number): string {
  return `${itemName}:${index}`;
}

export function exclusiveRivals(conditionalKey: string): string[] {
  const at = conditionalKey.lastIndexOf(':');
  const itemName = conditionalKey.slice(0, at);
  const index = Number(conditionalKey.slice(at + 1));
  const effects = GEAR_EFFECTS[itemName] ?? WEAPON_EFFECTS[itemName] ?? ARMOR_EFFECTS[itemName] ?? [];
  if (!effects[index]?.exclusive) return [];
  return effects.flatMap((effect, other) => (effect.exclusive && other !== index ? [itemConditionalKey(itemName, other)] : []));
}

// The wiki's swap list: "Fire & STR, Ice & SKI, Earth & DEF and Wind & CEL" (Burn, Frostbite, Poison, Confusion).
export const TETRA_PAIRS: Record<TetraAlignment, { stat: StatKey; status: string }> = {
  Fire: { stat: 'str', status: 'Burn' },
  Ice: { stat: 'ski', status: 'Frostbite' },
  Earth: { stat: 'def', status: 'Poison' },
  Wind: { stat: 'cel', status: 'Confusion' },
};

function effectKey(value: ItemEffectValue, tetra: TetraAlignment = 'Fire'): string {
  if (!value.tetra) return value.key;
  return value.kind === 'stat' ? TETRA_PAIRS[tetra].stat : tetra;
}

export function bonusesForItem(
  itemName: string | null | undefined,
  effects: ItemEffect[],
  ul: number,
  conditionals: Record<string, boolean>,
  into: ItemBonuses,
  rolls: Record<string, number> = NO_ROLLS,
  tetra?: TetraAlignment,
): ItemBonuses {
  if (!itemName) return into;
  effects.forEach((effect, index) => {
    if (effect.applies === 'reference') return;
    if (effect.applies === 'conditional' && !conditionals[itemConditionalKey(itemName, index)]) return;
    effect.effects.forEach((value, valueIndex) => {
      const amount = valueAtUL(value, ul, rolls[itemRollKey(itemName, index, valueIndex)]);
      if (!amount) return;
      const valueKey = effectKey(value, tetra);
      if (value.kind === 'buffStat') {
        const key = `buff:${valueKey}`;
        into.derived[key] = (into.derived[key] ?? 0) + amount;
      } else if (value.kind === 'stat') {
        const key = valueKey as StatKey;
        into.stats[key] = (into.stats[key] ?? 0) + amount;
      } else if (value.kind === 'elementalAttack') {
        const key = valueKey as ElementKey;
        into.elementalAttack[key] = (into.elementalAttack[key] ?? 0) + amount;
      } else if (value.kind === 'resistance') {
        const key = valueKey as ResistKey;
        into.resistances[key] = (into.resistances[key] ?? 0) + amount;
      } else {
        into.derived[valueKey] = (into.derived[valueKey] ?? 0) + amount;
      }
    });
  });
  return into;
}

export interface GearSlotInput {
  itemName?: string | null;
  /** `object`, not `Record<string, number>`: the per-slot interfaces have no index signature. */
  upgradePoints?: object;
  tetra?: TetraAlignment;
}

export function gearUL(points: object | undefined): number {
  if (!points) return 0;
  return Object.values(points).reduce<number>((total, value) => total + (Number(value) || 0), 0);
}

export function itemBonuses(input: {
  weaponName?: string | null;
  armorName?: string | null;
  weaponPoints?: WeaponUpgradePoints;
  armorPoints?: ArmorUpgradePoints;
  gear?: Array<GearSlotInput | undefined>;
  conditionals?: Record<string, boolean>;
  rolls?: Record<string, number>;
}): ItemBonuses {
  const weapons = weaponEffects(input.weaponName);
  const armors = armorEffects(input.armorName);
  const gear = input.gear;
  let hasGear = false;
  if (gear) {
    for (const slot of gear) {
      if (slot?.itemName && gearEffects(slot.itemName).length) { hasGear = true; break; }
    }
  }
  if (!weapons.length && !armors.length && !hasGear) return EMPTY;

  const conditionals = input.conditionals ?? {};
  const rolls = input.rolls ?? NO_ROLLS;
  const result: ItemBonuses = { stats: {}, derived: {}, elementalAttack: {}, resistances: {} };
  bonusesForItem(input.weaponName, weapons, weaponUL(input.weaponPoints), conditionals, result, rolls);
  bonusesForItem(input.armorName, armors, armorUL(input.armorPoints), conditionals, result, rolls);
  if (gear) {
    for (const slot of gear) {
      if (!slot?.itemName) continue;
      const effects = gearEffects(slot.itemName);
      if (!effects.length) continue;
      bonusesForItem(slot.itemName, effects, gearUL(slot.upgradePoints), conditionals, result, rolls, slot.tetra);
    }
  }
  return result;
}
